1	import { useLayoutEffect, useRef } from "react";
2	import { prefersReducedMotion } from "../mascot/mascotStore";
3	import { onboardingPhotos } from "./onboardingMedia";
4	
5	type Layer = "far" | "mid" | "near";
6	type FloatCard = { src: string; layer: Layer; x: number; y: number; w: number; h: number };
7	
8	const p = onboardingPhotos;
9	
10	// Positions and sizes come straight from the "Onboarding 2 · Every kind of
11	// thing" board in Paper, in the 960x540 stage's own pixels.
12	const CARDS: FloatCard[] = [
13	  { src: p.deskPlant, layer: "far", x: 10, y: 80, w: 71, h: 71 },
14	  { src: p.record, layer: "far", x: 870, y: 74, w: 71, h: 71 },
15	  { src: p.sprig, layer: "far", x: 411, y: 12, w: 58, h: 87 },
16	  { src: p.pottery, layer: "mid", x: 206, y: 396, w: 89, h: 89 },
17	  { src: p.field, layer: "mid", x: 110, y: 129, w: 110, h: 73 },
18	  { src: p.daisy, layer: "mid", x: 668, y: 52, w: 94, h: 85 },
19	  { src: p.delphinium, layer: "mid", x: 702, y: 395, w: 67, h: 120 },
20	  { src: p.sea, layer: "near", x: 753, y: 170, w: 134, h: 89 },
21	  { src: p.vases, layer: "near", x: 797, y: 302, w: 95, h: 126 },
22	  { src: p.book, layer: "near", x: 523, y: 435, w: 134, h: 89 },
23	  { src: p.stairs, layer: "near", x: 281, y: 401, w: 98, h: 122 },
24	  { src: p.monstera, layer: "near", x: 67, y: 232, w: 89, h: 134 },
25	  { src: p.sketching, layer: "near", x: 245, y: 20, w: 110, h: 110 },
26	  { src: p.car, layer: "near", x: 513, y: 28, w: 134, h: 89 },
27	];
28	
29	/** How strongly each layer follows the pointer and drifts; near moves most. */
30	const DEPTH: Record<Layer, number> = { far: 0.3, mid: 0.6, near: 1 };
31	const PARALLAX_PX = 22;
32	const DRIFT_PX = 6;
33	
34	/**
35	 * Screen two's backdrop: photos floating at three depths around the copy, as
36	 * on the Paper board. Fancy Components' Parallax Floating drives it: the
37	 * pointer pulls near photos further than far ones, and each photo drifts on
38	 * its own slow path, Drift Wall style.
39	 *
40	 * One rAF loop writes transforms straight to the photos, so React renders this
41	 * once. The loop only lives while the screen is mounted; reduced motion gets
42	 * the board's still layout.
43	 */
44	export function KeptFloating() {
45	  const cardRefs = useRef<(HTMLImageElement | null)[]>([]);
46	
47	  useLayoutEffect(() => {
48	    if (prefersReducedMotion()) return;
49	
50	    const pointer = { x: 0, y: 0 };
51	    const eased = { x: 0, y: 0 };
52	    const onPointerMove = (event: PointerEvent) => {
53	      pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
54	      pointer.y = (event.clientY / window.innerHeight) * 2 - 1;
55	    };
56	    window.addEventListener("pointermove", onPointerMove);
57	
58	    let raf = 0;
59	    let start = 0;
60	    const tick = (ms: number) => {
61	      raf = requestAnimationFrame(tick);
62	      if (!start) start = ms;
63	      const seconds = (ms - start) / 1000;
64	      eased.x += (pointer.x - eased.x) * 0.06;
65	      eased.y += (pointer.y - eased.y) * 0.06;
66	      CARDS.forEach((card, index) => {
67	        const el = cardRefs.current[index];
68	        if (!el) return;
69	        const depth = DEPTH[card.layer];
70	        const driftX = Math.sin(seconds * 0.23 + index * 2.1) * DRIFT_PX * depth;
71	        const driftY = Math.cos(seconds * 0.31 + index * 1.3) * DRIFT_PX * depth;
72	        const x = driftX - eased.x * PARALLAX_PX * depth;
73	        const y = driftY - eased.y * PARALLAX_PX * depth;
74	        el.style.transform = `translate3d(${x}px, ${y}px, 0)`;
75	      });
76	    };
77	    raf = requestAnimationFrame(tick);
78	    return () => {
79	      cancelAnimationFrame(raf);
80	      window.removeEventListener("pointermove", onPointerMove);
81	    };
82	  }, []);
83	
84	  return (
85	    <div className="kept-floating" aria-hidden="true">
86	      {CARDS.map((card, index) => (
87	        <img
88	          key={card.src}
89	          ref={(el) => {
90	            cardRefs.current[index] = el;
91	          }}
92	          className={`kept-photo is-${card.layer}`}
93	          src={card.src}
94	          alt=""
95	          draggable={false}
96	          style={{ left: card.x, top: card.y, width: card.w, height: card.h }}
97	        />
98	      ))}
99	    </div>
100	  );
101	}
