13	import sprig from "../../assets/onboarding/sprig.webp";
14	import stairs from "../../assets/onboarding/stairs.webp";
15	import vases from "../../assets/onboarding/vases.webp";
16	
17	/**
18	 * The welcome screens' pictures: small webp thumbnails of the photos on the
19	 * Paper onboarding boards, bundled with the app.
20	 */
21	export const onboardingPhotos = {
22	  book,
23	  car,
24	  daisy,
25	  delphinium,
26	  deskPlant,
27	  field,
28	  monstera,
29	  pottery,
30	  record,
31	  redRocks,
32	  sea,
33	  sketching,
34	  sprig,
35	  stairs,
36	  vases,
37	};
38	
39	/** Decode every picture up front, so no later screen pops its images in. */
40	export function preloadOnboardingPhotos() {
41	  for (const src of Object.values(onboardingPhotos)) {
42	    const image = new Image();
43	    image.src = src;
44	    void image.decode().catch(() => null);
45	  }
46	}
