1	import { useEffect, useState, type CSSProperties } from "react";
2	import {
3	  Breadcrumb,
4	  BreadcrumbItem,
5	  BreadcrumbList,
6	  BreadcrumbPage,
7	  BreadcrumbSeparator,
8	} from "./Breadcrumb";
9	import { KeptFloating } from "./onboarding/KeptFloating";
10	import { MemoryMatch } from "./onboarding/MemoryMatch";
11	import { OnboardingMascot } from "./onboarding/OnboardingMascot";
12	import { preloadOnboardingPhotos } from "./onboarding/onboardingMedia";
13	import { ReadsPictures } from "./onboarding/ReadsPictures";
14	import { SplitText } from "./onboarding/SplitText";
15	
16	const STAGE_WIDTH = 960;
17	const STAGE_HEIGHT = 540;
18	const LAST_SCREEN = 4;
19	/** Drawn size of the big cropped mascot at stage scale 1; the body is about 63% of it. */
20	const MASCOT_SIZE = 620;
21	
22	const welcomeFaces = ["neutre", "curieux", "heureux", "attentif"] as const;
23	const farewellFaces = ["heureux", "neutre", "fier", "timide"] as const;
24	
25	function fitScale() {
26	  return Math.min(1, window.innerWidth / STAGE_WIDTH, window.innerHeight / STAGE_HEIGHT);
27	}
28	
29	export function FirstRunOverlay({ onFinish }: { onFinish: () => void }) {
30	  const [screen, setScreen] = useState(0);
31	  const [scale, setScale] = useState(fitScale);
32	
33	  useEffect(() => {
34	    const update = () => setScale(fitScale());
35	    const onKeyDown = (event: KeyboardEvent) => {
36	      if (event.key === "Escape") onFinish();
37	    };
38	    window.addEventListener("resize", update);
39	    window.addEventListener("keydown", onKeyDown);
40	    return () => {
41	      window.removeEventListener("resize", update);
42	      window.removeEventListener("keydown", onKeyDown);
43	    };
44	  }, [onFinish]);
45	
46	  // First launch keeps the window hidden until this screen has painted, and
47	  // the later screens' photos decode meanwhile so none of them pop in.
48	  useEffect(() => {
49	    preloadOnboardingPhotos();
50	    let frame = requestAnimationFrame(() => {
51	      frame = requestAnimationFrame(
52	        () => void window.inkling?.windowControls.ready().catch(() => null),
53	      );
54	    });
55	    return () => cancelAnimationFrame(frame);
56	  }, []);
57	
58	  const advance = () => (screen === LAST_SCREEN ? onFinish() : setScreen(screen + 1));
59	
60	  const actions = (style: CSSProperties) => (
61	    <div className="first-run-actions" style={style}>
62	      <button type="button" className="first-run-primary" onClick={advance}>
63	        {screen === LAST_SCREEN ? "Open my library" : "Continue"}
64	      </button>
65	      {screen > 0 ? (
66	        <button type="button" className="first-run-quiet" onClick={() => setScreen(screen - 1)}>
67	          Back
68	        </button>
69	      ) : null}
70	      <button type="button" className="first-run-quiet" onClick={onFinish}>
71	        Skip
72	      </button>
73	    </div>
74	  );
75	
76	  const mascotSize = MASCOT_SIZE * scale;
77	
78	  return (
79	    <div
80	      className="first-run-overlay"
81	      role="dialog"
82	      aria-modal="true"
83	      aria-label="Welcome to inkling"
84	    >
85	      {/* The big mascot hangs off the window's corner, not the stage's, so it
86	          stays cropped by the window edge at any size. */}
87	      {screen === 0 ? (
88	        <OnboardingMascot
89	          key="welcome"
90	          size={mascotSize}
91	          faces={welcomeFaces}
92	          style={{ right: -0.2 * mascotSize, bottom: -0.3 * mascotSize }}
93	        />
94	      ) : null}
95	      {screen === LAST_SCREEN ? (
96	        <OnboardingMascot
97	          key="farewell"
98	          size={mascotSize}
99	          faces={farewellFaces}
100	          style={{ left: -0.22 * mascotSize, bottom: -0.3 * mascotSize }}
101	        />
102	      ) : null}
103	
104	      <div
105	        key={screen}
106	        className="first-run-stage"
107	        style={{ transform: `translate(-50%, -50%) scale(${scale})` }}
108	      >
109	        {screen === 0 ? (
110	          <>
111	            <SplitText
112	              text="Drop something in."
113	              className="first-run-headline"
114	              style={{ left: 72, top: 156 }}
115	            />
116	            <p className="first-run-body" style={{ left: 72, top: 221 }}>
117	              Paste a link, drop in a file, or grab a screenshot.
118	              <br />
119	              It&apos;s kept the moment it lands. No folders to pick.
120	            </p>
121	            <div className="first-run-keys" style={{ left: 72, top: 291 }}>
122	              <kbd>Ctrl</kbd>
123	              <kbd>V</kbd>
124	              <span>works anywhere in inkling</span>
125	            </div>
126	            {actions({ left: 72, top: 348 })}
127	          </>
128	        ) : null}
129	
130	        {screen === 1 ? (
131	          <>
132	            <KeptFloating />
133	            <SplitText
134	              text="Kept as it came."
135	              className="first-run-headline is-centered"
136	              style={{ top: 164 }}
137	            />
138	            <p className="first-run-body is-centered" style={{ top: 232 }}>
139	              Articles, photos, PDFs, quotes, notes and posts each get
140	              <br />
141	              their own card, right away. Reading and indexing happen
142	              <br />
143	              quietly while you keep going.
144	            </p>
145	            {actions({ top: 337, left: 0, right: 0, justifyContent: "center" })}
146	          </>
147	        ) : null}
148	
149	        {screen === 2 ? (
150	          <>
151	            <MemoryMatch />
152	            <SplitText
153	              text="Half a memory is enough."
154	              className="first-run-headline is-centered"
155	              style={{ top: 311 }}
156	            />
157	            <p className="first-run-body is-centered" style={{ top: 375 }}>
158	              Describe it the way it comes back to you. Search runs on this
159	              <br />
160	              computer, so nothing you save leaves it.
161	            </p>
162	            {actions({ top: 448, left: 0, right: 0, justifyContent: "center" })}
163	          </>
164	        ) : null}
165	
166	        {screen === 3 ? (
167	          <>
168	            <ReadsPictures />
169	            <SplitText
170	              text="It reads your pictures, too."
171	              className="first-run-headline is-wrapped"
172	              style={{ left: 72, top: 92, width: 390 }}
173	            />
174	            <p className="first-run-body" style={{ left: 72, top: 230 }}>
175	              Words inside screenshots, photos and PDFs are
176	              <br />
177	              searchable. Remember one word, find the whole
178	              <br />
179	              thing. All on this computer.
180	            </p>
181	            <div className="first-run-keys" style={{ left: 72, top: 336 }}>
182	              <kbd>Ctrl</kbd>
