/** The ring around the copy, in stage pixels (the stage is 960x540). */
const CENTER_X = 480;
const CENTER_Y = 270;
const RADIUS_X = 430;
const RADIUS_Y = 240;
/** Seconds for a card to travel the whole ring. */
const ORBIT_SECONDS = 90;
/** Where the ring is already turned to when the screen opens, as a fraction of it. */
const START_PHASE = 0.02;

/** How strongly each layer follows the pointer and drifts; near moves most. */
const DEPTH: Record<Layer, number> = { far: 0.3, mid: 0.6, near: 1 };
const PARALLAX_PX = 22;
const DRIFT_PX = 6;

/**
 * Points along the ring at equal steps of arc length, so cards sit evenly and
 * move at one steady speed. A plain angle would bunch them up at the sides.
 */
const RING_SAMPLES = 360;
const RING = (() => {
  const points: { x: number; y: number }[] = [];
  const lengths = [0];
  for (let i = 0; i <= RING_SAMPLES; i += 1) {
    // Screen y points down, so a growing angle runs counter-clockwise on screen:
    // leftward along the top, down the left side, rightward along the bottom.
    const angle = (i / RING_SAMPLES) * Math.PI * 2;
    points.push({
      x: CENTER_X + Math.cos(angle) * RADIUS_X,
      y: CENTER_Y - Math.sin(angle) * RADIUS_Y,
    });
    if (i > 0) {
      const a = points[i - 1];
      const b = points[i];
      lengths.push(lengths[i - 1] + Math.hypot(b.x - a.x, b.y - a.y));
    }
  }
  return { points, lengths, total: lengths[RING_SAMPLES] };
})();

function ringPoint(fraction: number) {
  const target = (((fraction % 1) + 1) % 1) * RING.total;
  let low = 0;
  let high = RING_SAMPLES;
  while (high - low > 1) {
    const mid = (low + high) >> 1;
    if (RING.lengths[mid] <= target) low = mid;
    else high = mid;
  }
  const span = RING.lengths[high] - RING.lengths[low];
  const t = span === 0 ? 0 : (target - RING.lengths[low]) / span;
  const a = RING.points[low];
  const b = RING.points[high];
  return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
}

function CardBody({ content }: { content: Content }): ReactNode {
  switch (content.kind) {
    case "photo":
      return <img className="kept-fill" src={content.src} alt="" draggable={false} />;
    case "video":
      return (
        <>
          <img className="kept-fill" src={content.src} alt="" draggable={false} />
          <span className="kept-scrim" />
          <span className="kept-play">
            <HugeiconsIcon icon={PlayIcon} size={14} />
          </span>
          <span className="kept-badge">{content.duration}</span>
        </>
      );
    case "article":
      return (
        <>
          <img className="kept-article-image" src={content.src} alt="" draggable={false} />
          <div className="kept-article-text">
            <span className="kept-kicker">Article</span>
            <strong>{content.title}</strong>
            <span className="kept-domain">{content.domain}</span>
          </div>
        </>
      );
    case "note":
      return (
        <div className="kept-note">
          <span className="kept-kicker is-note">Note</span>
          <strong>{content.title}</strong>
          <p>{content.text}</p>
        </div>
      );
    case "pdf":
      return (
        <div className="kept-pdf">
          <span className="kept-pdf-label">PDF</span>
          <strong>{content.title}</strong>
          <span className="kept-pdf-rule" />
          <span className="kept-domain">{content.pages}</span>
        </div>
      );
    case "quote":
      return (
        <div className="kept-quote">
          <span className="kept-quote-mark">“</span>
          <p>{content.text}</p>
          <span className="kept-domain">— {content.by}</span>
        </div>
      );
  }
}

/**
 * Screen two's backdrop: mini cards of every kind circling the copy, counter-
 * clockwise, at three depths. Fancy Components' Parallax Floating drives it:
 * the pointer pulls near cards further than far ones, and each card also
 * drifts a little on its own slow path.
 *
 * One rAF loop writes transforms straight to the cards, so React renders this
 * once. The loop only lives while the screen is mounted; reduced motion gets a
 * still ring.
 */
export function KeptFloating() {
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);

  useLayoutEffect(() => {
    const pointer = { x: 0, y: 0 };
    const eased = { x: 0, y: 0 };

    const place = (seconds: number) => {
      CARDS.forEach((card, index) => {
        const el = cardRefs.current[index];
        if (!el) return;
        const depth = DEPTH[card.layer];
        const ring = ringPoint(index / CARDS.length + START_PHASE + seconds / ORBIT_SECONDS);
        const driftX = Math.sin(seconds * 0.23 + index * 2.1) * DRIFT_PX * depth;
        const driftY = Math.cos(seconds * 0.31 + index * 1.3) * DRIFT_PX * depth;
        const x = ring.x - card.w / 2 + driftX - eased.x * PARALLAX_PX * depth;
        const y = ring.y - card.h / 2 + driftY - eased.y * PARALLAX_PX * depth;
        el.style.transform = `translate3d(${x}px, ${y}px, 0)`;
      });
    };

    place(0);
    if (prefersReducedMotion()) return;

    const onPointerMove = (event: PointerEvent) => {
      pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
      pointer.y = (event.clientY / window.innerHeight) * 2 - 1;
    };
    window.addEventListener("pointermove", onPointerMove);

    let raf = 0;
    let start = 0;
    const tick = (ms: number) => {
      raf = requestAnimationFrame(tick);
      if (!start) start = ms;
      eased.x += (pointer.x - eased.x) * 0.06;
      eased.y += (pointer.y - eased.y) * 0.06;
      place((ms - start) / 1000);
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onPointerMove);
    };
  }, []);

  return (
    <div className="kept-floating" aria-hidden="true">
      {CARDS.map((card, index) => (
        <div
          // The ring order is fixed and the list never changes.
          // biome-ignore lint/suspicious/noArrayIndexKey: static list
          key={index}
          ref={(el) => {
            cardRefs.current[index] = el;
          }}
          className={`kept-card is-${card.layer} is-${card.content.kind}`}
          style={{ width: card.w, height: card.h }}
        >
          <CardBody content={card.content} />
        </div>
      ))}
    </div>
  );
}

